"""
    Adds totals from item to totals

    :param dict totals: Totals to be added to
    :param dict item: Item to be added to totals dict
    :return: totals dict
    :rtype: dict
    """
def add_to_tracking_totals(totals: Any, item: Any) -> object {
    for (key, value) in item.items() {
        if (
            (
                (`type(value) is int)
                and (key not in ["GP", "W", "L", "TEAM_ID", "PLAYER_ID"])
            )
            or (
                key
                in [
                    "MIN",
                    "DIST_MILES",
                    "DIST_MILES_OFF",
                    "DIST_MILES_DEF",
                    "TIME_OF_POSS"
                ]
            )
        ) {
            if (value is not None) {
                totals[key] = totals.get(key, 0) + value;
            }
        }
    }
    return totals;
}

